#!/bin/bash
# PROTOTYPE throwaway — incremental delta assembly (wayfinder #186, rig real/).
# Generated by scripts/gen-set-delta.sh: FROM the parent set image, COPY only
# the NEW members' dumps, one RUN extracting just them + merging PM state
# (parent status + new dumps, new-wins — same last-writer rule, but the new
# member is applied after the parent instead of in alphabetical order).
# NOTE for the map: contested packages resolve new-wins here, not
# alphabetical-last-wins as in full canonical assembly — flagged, not decided.
set -euo pipefail

for tc in "$@"; do
  t0=$(date +%s.%N)
  tar xzf "/rig/$tc/payload.tar.gz" -C /
  stamp() { awk -v label="$1" -v a="$2" -v b="$(date +%s.%N)" 'BEGIN{printf "assemble-delta: %s %.1fs\n", label, b-a}'; }
  stamp "extract $tc" "$t0"
  tar xzf "/rig/$tc/pm-info.tar.gz" -C /var/lib/dpkg
done

t0=$(date +%s.%N)
python3 - "$@" <<'PY'
import os, sys

files = ['/var/lib/dpkg/status'] + ['/rig/%s/pm-status' % tc for tc in sys.argv[1:]]
stanzas = {}
for path in files:
    pkg, buf = None, []

    def flush(pkg, buf):
        if pkg is not None and buf:
            stanzas[pkg] = '\n'.join(buf) + '\n'

    with open(path) as f:
        for line in f:
            line = line.rstrip('\n')
            if not line:
                flush(pkg, buf)
                pkg, buf = None, []
            else:
                buf.append(line)
                if line.startswith('Package: '):
                    pkg = line[len('Package: '):]
    flush(pkg, buf)

with open('/var/lib/dpkg/status.merge', 'w') as f:
    for s in stanzas.values():
        f.write(s + '\n')
os.replace('/var/lib/dpkg/status.merge', '/var/lib/dpkg/status')
print('assemble-delta: %d stanzas merged' % len(stanzas))
PY
ldconfig
stamp() { awk -v label="$1" -v a="$2" -v b="$(date +%s.%N)" 'BEGIN{printf "assemble-delta: %s %.1fs\n", label, b-a}'; }
stamp "merge+ldconfig" "$t0"
rm -rf /rig
